1	/**
2	 * What a lesson *serves* — and the schema the in-house decks are written to.
3	 *
4	 * The content-source seam: `LessonContent` is a two-arm discriminated union so
5	 * a lesson can serve either a licensed `.webm` or an in-house deck, one lesson
6	 * at a time, with the compiler refusing any dispatch that forgets an arm.
7	 *
8	 * The deck schema's one non-structural demand is **retrieval**: a deck is
9	 * invalid unless the learner is asked to attempt something before the answer
10	 * is shown. A guideline would be honoured by the first deck and forgotten by
11	 * the twelfth; a schema rule is checked on every deck for free.
12	 */
13	
14	import {
15		type LessonSequenceEntry,
16		lessonEntryById,
17		parseLessonId,
18	} from "./lessonSequence";
19	import { type Lesson, lessons, specialRules, toneRules } from "./symbols";
20	
21	// ============================================================================
22	// The content union
23	// ============================================================================
24	
25	export type LessonContent =
26		| { readonly kind: "video"; readonly url: string }
27		| { readonly kind: "deck"; readonly deckPath: string };
28	
29	/**
30	 * Exhaustive dispatch over `LessonContent`. The `never` default is the point:
31	 * adding a third arm without handling it here is a compile error, which is how
32	 * every downstream dispatch is kept honest too.
33	 */
34	export function describeLessonContent(content: LessonContent): string {
35		switch (content.kind) {
36			case "video":
37				return `video ${content.url}`;
38			case "deck":
39				return `deck ${content.deckPath}`;
40			default: {
41				const _never: never = content;
42				return _never;
43			}
44		}
45	}
46	
47	// ============================================================================
48	// Asset paths
49	// ============================================================================
50	
51	/**
52	 * Public root under which every generated lesson asset lives. Includes the
53	 * app's deploy base path (`vite.config.ts`'s `base: "/thai-script/"`) —
54	 * every other asset URL in this codebase (`symbols.ts`'s `videoUrl` and
55	 * `audioUrl` fields) is hardcoded the same way, and a root that omits it
56	 * 404s once the app is actually served under that base, dev included.
57	 */
58	export const LESSON_ASSET_ROOT = "/thai-script/lessons";
59	
60	export type DeckPathResult =
61		| { readonly ok: true; readonly path: string }
62		| { readonly ok: false; readonly error: string };
63	
64	/**
65	 * The one place a filesystem/URL path is derived from a lesson id, and so the
66	 * one place the charset has to hold. Task 1.3 owns the containment check at
67	 * the generator's write boundary; this owns the charset.
68	 */
69	export function deckPathForLesson(
70		value: unknown,
71		key = "lessonId",
72	): DeckPathResult {
73		const parsed = parseLessonId(value, key);
74		if (!parsed.ok) return parsed;
75		return { ok: true, path: `${LESSON_ASSET_ROOT}/${parsed.id}/deck.json` };
76	}
77	
78	// ============================================================================
79	// Resolution — three states, and "unresolvable" never reads as "undeclared"
80	// ============================================================================
81	
82	/**
83	 * Lessons whose content is an in-house deck. Empty at the end of task 1.1a:
84	 * every lesson still serves its video. Task 1.4 adds `lesson-01`, and each
85	 * later content task adds its own — that addition is the whole strangler.
86	 *
87	 * `lesson-sound-buckets` is deliberately absent: it has no `legacyNumber` in
88	 * `lessonSequence.ts` yet, and giving it one is a lesson-identity decision
89	 * (CONTEXT.md Rule 1 — the five-store hazard) that belongs with the task
90	 * that owns that migration, not a one-line addition here. Its deck is
91	 * committed and schema-valid (see `openingBand.test.ts`) but unreachable
92	 * from any route until that sequencing decision is made.
93	 */
94	export const DECK_LESSON_IDS: ReadonlySet<string> = new Set<string>([
95		"lesson-01",
96		"lesson-02",
97		"lesson-03",
98		"lesson-04",
99		"lesson-05",
100		// Phase 3's middle band. Each of these six already held a slot in
101		// `lessonSequence.ts` with its legacy number and a `lessons` row, so the
102		// symbols each teaches, and the lesson each symbol is filed under, are
103		// unchanged — only the content source moves from the licensed video to the
104		// in-house deck.
105		"lesson-06",
106		"lesson-07",
107		"lesson-08",
108		"lesson-09",
109		"lesson-10",
110		"lesson-11",
111		// Phase 3's three promoted lessons. Each already holds a slot in
112		// `lessonSequence.ts` with a `legacyNumber` and a `lessons` row, so wiring
113		// them onto the deck arm moves no lesson's position and touches none of the
114		// five persisted stores (CONTEXT.md Rule 1).
115		"lesson-unwritten-vowels",
116		"lesson-clusters",
117		"lesson-leading-consonants",
118		// Task 4.2 — the consolidated tone-mark lesson. Already holds a slot in
119		// `lessonSequence.ts` with its own legacy number and `lessons` row.
120		"lesson-tone-marks",
121	]);
122	
123	export type LessonContentResolution =
124		/** Declared, and its content source is known. */
125		| { readonly status: "resolved"; readonly content: LessonContent }
126		/** Declared, but no content source can be produced — with the reason. */
127		| { readonly status: "unresolvable"; readonly reason: string }
128		/** No lesson with this id is declared at all. */
129		| { readonly status: "undeclared" };
130	
131	/**
132	 * The three statuses are distinct values on purpose: a lesson whose video is
133	 * missing must never be indistinguishable from a lesson that does not exist,
134	 * because the first is a broken build and the second is an ordinary 404.
135	 */
136	export const LESSON_CONTENT_STATUSES = [
137		"resolved",
138		"unresolvable",
139		"undeclared",
140	] as const;
141	
142	/**
143	 * Content for a lesson that is known to be declared, so the only two outcomes
144	 * left are "resolved" and "unresolvable". Split out from `resolveLessonContent`
145	 * because the undeclared case is decided by the lookup and this one is not —
146	 * a lesson whose video went missing must never read as a lesson that does not
147	 * exist.
148	 */
149	export function lessonContentFor(
150		entry: LessonSequenceEntry,
151		lesson: Lesson | undefined,
152	): LessonContentResolution {
153		if (DECK_LESSON_IDS.has(entry.id)) {
154			const path = deckPathForLesson(entry.id);
155			if (!path.ok) return { status: "unresolvable", reason: path.error };
156			return {
157				status: "resolved",
158				content: { kind: "deck", deckPath: path.path },
159			};
160		}
161		if (!lesson) {
162			return {
163				status: "unresolvable",
164				reason:
165					"lessonId: declared in the sequence but absent from the lessons table",
166			};
167		}
168		if (!lesson.videoUrl) {
169			return {
170				status: "unresolvable",
171				reason: "lessonId: declares neither a deck nor a video url",
172			};
173		}
174		return {
175			status: "resolved",
176			content: { kind: "video", url: lesson.videoUrl },
177		};
178	}
179	
180	export function resolveLessonContent(value: unknown): LessonContentResolution {
181		const lookup = lessonEntryById(value);
182		if (!lookup.ok) return { status: "undeclared" };
183		const entry = lookup.entry;
184		return lessonContentFor(
185			entry,
186			lessons.find((lesson) => lesson.number === entry.legacyNumber),
187		);
188	}
189	
190	// ============================================================================
191	// The rules block
192	// ============================================================================
193	
194	/**
195	 * A rule a lesson teaches, resolved from the tables that already declare it
196	 * (`toneRules`, `specialRules`) via the ids the lessons table already lists.
197	 * Rule slides render from this — they carry no prose of their own, so the
198	 * slide and the rule cannot drift apart.
199	 */
200	export interface LessonRule {
201		readonly id: string;
202		readonly kind: "tone" | "special";
203		readonly title: string;
204		readonly text: string;
205	}
206	
207	export function lessonRules(legacyNumber: number): readonly LessonRule[] {
208		const lesson = lessons.find((candidate) => candidate.number === legacyNumber);
209		if (!lesson) return [];
210	
211		const tone = lesson.toneRulesIntroduced.flatMap<LessonRule>((id) => {
212			const rule = toneRules.find((candidate) => candidate.id === id);
213			if (!rule) return [];
214			return [
215				{
216					id: rule.id,
217					kind: "tone",
218					title: `${rule.consonantClass} class + ${rule.syllableType} syllable = ${rule.resultingTone} tone`,
219					text: rule.description,
220				},
221			];
222		});
223		const special = lesson.specialRulesIntroduced.flatMap<LessonRule>((id) => {
224			const rule = specialRules.find((candidate) => candidate.id === id);
225			if (!rule) return [];
226			return [
227				{
228					id: rule.id,
229					kind: "special",
230					title: rule.title,
231					text: rule.description,
232				},
233			];
234		});
235		return [...tone, ...special];
236	}
237	
238	// ============================================================================
239	// The deck schema
240	// ============================================================================
241	
242	export interface DeckExpositionSlide {
243		readonly kind: "exposition";
244		readonly id: string;
245		readonly heading: string;
246		readonly body: readonly string[];
247	}
248	
249	/**
250	 * A prompt the learner attempts. It names the reveal that answers it and
251	 * carries no answer itself — the attempt is the mechanism, so an answer
252	 * sitting on the same slide defeats the slide entirely.
253	 */
254	export interface DeckRetrievalSlide {
255		readonly kind: "retrieval";
256		readonly id: string;
257		readonly prompt: string;
258		readonly revealSlideId: string;
259	}
260	
261	export interface DeckRevealSlide {
262		readonly kind: "reveal";
263		readonly id: string;
264		readonly retrievalSlideId: string;
265		readonly answers: readonly string[];
266	}
267	
268	/** Renders from the lesson's rules block; holds no prose of its own. */
269	export interface DeckRuleSlide {
270		readonly kind: "rule";
271		readonly id: string;
272		readonly ruleId: string;
273	}
274	
275	export type DeckSlide =
276		| DeckExpositionSlide
277		| DeckRetrievalSlide
278		| DeckRevealSlide
279		| DeckRuleSlide;
280	
281	export interface LessonDeck {
282		readonly lessonId: string;
283		readonly title: string;
284		readonly slides: readonly DeckSlide[];
285	}
286	
287	export type DeckErrorCode =
288		| "malformed"
289		| "lesson-id-refused"
290		| "duplicate-slide-id"
291		| "retrieval-answer-on-same-slide"
292		| "dangling-reveal"
293		| "reveal-before-retrieval"
294		| "missing-retrieval"
295		| "unknown-rule"
296		| "rule-slide-carries-prose";
297	
298	export interface DeckValidationError {
299		readonly code: DeckErrorCode;
300		readonly message: string;
301		readonly slideId?: string;
302	}
303	
304	export type DeckValidationResult =
305		| { readonly ok: true; readonly deck: LessonDeck }
306		| { readonly ok: false; readonly errors: readonly DeckValidationError[] };
307	
308	/** Keys that would put an answer on the retrieval slide itself. */
309	const ANSWER_KEYS = ["answer", "answers", "reveal", "solution"] as const;
310	/** Keys that would let a rule slide state a rule differently from the block. */
311	const PROSE_KEYS = ["heading", "body", "text", "description"] as const;
312	
313	function isRecord(value: unknown): value is Record<string, unknown> {
314		return typeof value === "object" && value !== null && !Array.isArray(value);
315	}
316	
317	function isStringArray(value: unknown): value is string[] {
318		return (
319			Array.isArray(value) && value.every((item) => typeof item === "string")
320		);
321	}
322	
323	function parseSlide(
324		raw: unknown,
325		index: number,
326		errors: DeckValidationError[],
327	): DeckSlide | undefined {
328		const at = `slides[${index}]`;
329		if (!isRecord(raw)) {
330			errors.push({ code: "malformed", message: `${at}: not an object` });
331			return undefined;
332		}
333		const id = raw.id;
334		if (typeof id !== "string" || id.length === 0) {
335			errors.push({ code: "malformed", message: `${at}: missing a string id` });
336			return undefined;
337		}
338	
339		switch (raw.kind) {
340			case "exposition": {
341				if (typeof raw.heading !== "string" || !isStringArray(raw.body)) {
342					errors.push({
343						code: "malformed",
344						slideId: id,
345						message: `${at}: an exposition slide needs a heading and a body of strings`,
346					});
347					return undefined;
348				}
349				return { kind: "exposition", id, heading: raw.heading, body: raw.body };
350			}
351			case "retrieval": {
352				if (
353					typeof raw.prompt !== "string" ||
354					typeof raw.revealSlideId !== "string"
355				) {
356					errors.push({
357						code: "malformed",
358						slideId: id,
359						message: `${at}: a retrieval slide needs a prompt and a revealSlideId`,
360					});
361					return undefined;
362				}
363				const leaked = ANSWER_KEYS.find((key) => key in raw);
364				if (leaked) {
365					errors.push({
366						code: "retrieval-answer-on-same-slide",
367						slideId: id,
368						message: `${at}: retrieval slide carries "${leaked}"; the answer must live on the reveal slide it names, not beside the prompt`,
369					});
370					return undefined;
371				}
372				return {
373					kind: "retrieval",
374					id,
375					prompt: raw.prompt,
376					revealSlideId: raw.revealSlideId,
377				};
378			}
379			case "reveal": {
380				if (
381					typeof raw.retrievalSlideId !== "string" ||
382					!isStringArray(raw.answers)
383				) {
384					errors.push({
385						code: "malformed",
386						slideId: id,
387						message: `${at}: a reveal slide needs a retrievalSlideId and answers`,
388					});
389					return undefined;
390				}
391				return {
392					kind: "reveal",
393					id,
394					retrievalSlideId: raw.retrievalSlideId,
395					answers: raw.answers,
396				};
397			}
398			case "rule": {
399				if (typeof raw.ruleId !== "string") {
400					errors.push({
401						code: "malformed",
402						slideId: id,
403						message: `${at}: a rule slide needs a ruleId`,
404					});
405					return undefined;
406				}
407				const prose = PROSE_KEYS.find((key) => key in raw);
408				if (prose) {
409					errors.push({
410						code: "rule-slide-carries-prose",
411						slideId: id,
412						message: `${at}: rule slide carries "${prose}"; a rule slide renders from the lesson's rules block so the two cannot disagree`,
413					});
414					return undefined;
415				}
416				return { kind: "rule", id, ruleId: raw.ruleId };
417			}
418			default:
419				errors.push({
420					code: "malformed",
421					slideId: id,
422					message: `${at}: unknown slide kind`,
423				});
424				return undefined;
425		}
426	}
427	
428	function checkRetrieval(
429		slides: readonly DeckSlide[],
430		errors: DeckValidationError[],
431	): void {
432		const retrievalsSeen = new Set<string>();
433		let pairs = 0;
434	
435		for (const slide of slides) {
436			if (slide.kind === "retrieval") {
437				retrievalsSeen.add(slide.id);
438				continue;
439			}
440			if (slide.kind !== "reveal") continue;
441	
442			const target = slides.find(
443				(candidate) =>
444					candidate.kind === "retrieval" &&
445					candidate.id === slide.retrievalSlideId,
446			);
447			if (!target) {
448				errors.push({
449					code: "dangling-reveal",
450					slideId: slide.id,
451					message: `reveal "${slide.id}" names no retrieval slide that exists`,
452				});
453				continue;
454			}
455			if (!retrievalsSeen.has(slide.retrievalSlideId)) {
456				errors.push({
457					code: "reveal-before-retrieval",
458					slideId: slide.id,
459					message: `reveal "${slide.id}" comes before the retrieval step it answers; the learner must attempt first`,
460				});
461				continue;
462			}
463			pairs += 1;
464		}
465	
466		if (pairs === 0) {
467			errors.push({
468				code: "missing-retrieval",
469				message:
470					"deck has no retrieval step before a reveal: a deck must ask the learner to attempt at least one answer before showing it",
471			});
472		}
473	}
474	
475	export function validateDeck(value: unknown): DeckValidationResult {
476		const errors: DeckValidationError[] = [];
477	
478		if (!isRecord(value)) {
479			return {
480				ok: false,
481				errors: [{ code: "malformed", message: "deck: not an object" }],
482			};
483		}
484		const lessonId = parseLessonId(value.lessonId, "lessonId");
485		if (!lessonId.ok) {
486			return {
487				ok: false,
488				errors: [{ code: "lesson-id-refused", message: lessonId.error }],
489			};
490		}
491		if (typeof value.title !== "string" || value.title.length === 0) {
492			errors.push({ code: "malformed", message: "deck: missing a title" });
493		}
494		if (!Array.isArray(value.slides)) {
495			return {
496				ok: false,
497				errors: [
498					...errors,
499					{ code: "malformed", message: "deck: slides must be an array" },
500				],
501			};
502		}
503	
504		const slides: DeckSlide[] = [];
505		const seenIds = new Set<string>();
506		value.slides.forEach((raw, index) => {
507			const slide = parseSlide(raw, index, errors);
508			if (!slide) return;
509			if (seenIds.has(slide.id)) {
510				errors.push({
511					code: "duplicate-slide-id",
512					slideId: slide.id,
513					message: `slides[${index}]: slide id is already used`,
514				});
515				return;
516			}
517			seenIds.add(slide.id);
518			slides.push(slide);
519		});
520	
521		checkRetrieval(slides, errors);
522	
523		const entry = lessonEntryById(lessonId.id);
524		const rules = entry.ok ? lessonRules(entry.entry.legacyNumber) : [];
525		for (const slide of slides) {
526			if (slide.kind !== "rule") continue;
527			if (!rules.some((rule) => rule.id === slide.ruleId)) {
528				errors.push({
529					code: "unknown-rule",
530					slideId: slide.id,
531					message: `rule slide "${slide.id}" names a rule this lesson does not declare`,
532				});
533			}
534		}
535	
536		if (errors.length > 0) return { ok: false, errors };
537		return {
538			ok: true,
539			deck: { lessonId: lessonId.id, title: value.title as string, slides },
540		};
541	}
542	
543	/**
544	 * The rendering source for a rule slide: the lesson's own rules-block entry.
545	 * There is no other text on the slide, which is what makes "the lesson applies
546	 * the rule as it states it" checkable at all.
547	 */
548	export function renderRuleSlide(
549		deck: LessonDeck,
550		slide: DeckRuleSlide,
551	): LessonRule | undefined {
552		const entry = lessonEntryById(deck.lessonId);
553		if (!entry.ok) return undefined;
554		return lessonRules(entry.entry.legacyNumber).find(
555			(rule) => rule.id === slide.ruleId,
556		);
