394	// ============================================================================
395	// AC5 — originality
396	// ============================================================================
397	
398	describe("AC5 — the lesson reuses no phrasing from the source transcripts", () => {
399		it("clears the shared originality check on every line of the deck", async () => {
400			const overlaps: string[] = [];
401			let checked = 0;
402			for (const text of textsOf()) {
403				const result = await checkOriginality(text);
404				if (result.status === "overlapping") {
405					overlaps.push(
406						`"${result.overlap.ngram}" (${result.overlap.sources.join(", ")}) in "${text}"`,
407					);
