430		it("references only files inside the lesson's own directory, and leaves none unreferenced", () => {
431			const directory = join(PUBLIC_LESSONS, LESSON_ID);
432			const path = deckPathForLesson(LESSON_ID);
433			expect(path).toEqual({
434				ok: true,
435				path: `/thai-script/lessons/${LESSON_ID}/deck.json`,
436			});
437			expect(existsSync(join(directory, "deck.json"))).toBe(true);
438			expect(existsSync(join(directory, "manifest.json"))).toBe(true);
439	
440			const manifest = JSON.parse(
441				readFileSync(join(directory, "manifest.json"), "utf-8"),
442			) as Manifest;
443			expect(manifest.lessonId).toBe(LESSON_ID);
444	
445			const referenced = new Set<string>();
446			for (const s of deck.slides) {
447				for (const audio of s.audio ?? []) referenced.add(audio);
448				if (s.image) referenced.add(s.image);
449			}
450			for (const asset of referenced) {
451				expect(
452					asset.startsWith(`/thai-script/lessons/${LESSON_ID}/`),
453					asset,
454				).toBe(true);
455				const file = asset.slice(`/thai-script/lessons/${LESSON_ID}/`.length);
456				expect(file).not.toContain("..");
457				expect(existsSync(join(directory, file)), asset).toBe(true);
458			}
459			const onDisk = readdirSync(directory).filter(
460				(name) => name !== "deck.json" && name !== "manifest.json",
