300		getLessonMasteryProgress(lessonNumber: number): {
301			total: number;
302			graduated: number;
303			percentage: number;
304		} {
305			const allCards = this.cardRepo.findAll("script") as ScriptPropertyCard[];
306			const lessonCards = allCards.filter((c) => c.lessonNumber === lessonNumber);
307			const total = lessonCards.length;
308			const graduated = lessonCards.filter(
309				(c) => !c.schedule.isInLearning,
310			).length;
311			return {
312				total,
313				graduated,
314				percentage: total === 0 ? 0 : graduated / total,
315			};
316		}
