318		isNextLessonAvailable(): boolean {
319			return this.getNextLesson() !== null;
320		}
321	
322		/**
323		 * Backfills already-completed lessons with any card the current generator
324		 * would now produce for them that isn't persisted yet, or an `audioUrl`
325		 * on a persisted card that previously had none. See
326		 * `reconcileGeneratedCards` for the exact, deliberately narrow rules.
327		 *
328		 * A card id that's genuinely new (not just patched) is recorded as a
329		 * pending catch-up for its lesson, so the learner gets a one-time intro
330		 * to it instead of it appearing cold in review — see `getPendingCatchUps`.
331		 */
332		reconcileCards(): void {
333			const persisted = (
334				this.cardRepo.findAll("script") as ScriptPropertyCard[]
335			).map((card) => card.toDTO() as PropertyCard);
336			const persistedIds = new Set(persisted.map((card) => card.id));
337			const generated = this.stateRepo
338				.getCompletedLessons()
339				.flatMap((lessonNumber) => generateCardsForLesson(lessonNumber));
340	
341			const newlyBackfilled = generated.filter(
342				(card) => !persistedIds.has(card.id),
343			);
344			const newIdsByLesson = new Map<number, string[]>();
345			for (const card of newlyBackfilled) {
346				const ids = newIdsByLesson.get(card.lessonNumber) ?? [];
347				ids.push(card.id);
348				newIdsByLesson.set(card.lessonNumber, ids);
349			}
350			for (const [lessonNumber, cardIds] of newIdsByLesson) {
351				this.stateRepo.addPendingCatchUp(lessonNumber, cardIds);
352			}
353	
354			const toSave = reconcileGeneratedCards(persisted, generated);
355			if (toSave.length === 0) return;
356	
357			this.cardRepo.saveAll(toSave.map(toEntity));
358		}
359	
360		/**
361		 * Already-completed lessons that gained new content since the learner
362		 * finished them (e.g. a symbol category wired up after the fact), scoped
363		 * down to just the new items so `LessonIntro` can walk through them
364		 * without repeating what was already taught.
365		 */
366		getPendingCatchUps(): Array<{
367			lessonNumber: number;
368			summary: LessonSummary;
369		}> {
370			const allCards = this.cardRepo.findAll("script") as ScriptPropertyCard[];
371	
372			return this.stateRepo
373				.getPendingCatchUps()
374				.map(({ lessonNumber, cardIds }) => {
375					const idSet = new Set(cardIds);
376					// A tone rule card has no glyph (`symbolCharacter` is ""), so it's
377					// keyed by its own card id instead, which is exactly the id
378					// `getLessonSummary` puts on `ToneRuleSummary.id`.
379					const newKeys = new Set(
380						allCards
381							.filter((card) => idSet.has(card.id))
382							.map((card) => card.symbolCharacter || card.id),
383					);
384					const full = this.getLessonSummary(lessonNumber);
385					return {
386						lessonNumber,
387						summary: {
388							...full,
389							videoUrl: undefined,
390							consonants: full.consonants.filter((c) => newKeys.has(c.character)),
391							vowels: full.vowels.filter((v) => newKeys.has(v.character)),
392							toneMarks: full.toneMarks.filter((t) => newKeys.has(t.character)),
393							rareVowels: full.rareVowels.filter((v) => newKeys.has(v.character)),
394							numerals: full.numerals.filter((n) => newKeys.has(n.character)),
395							toneRules: full.toneRules.filter((r) => newKeys.has(r.id)),
396						},
397					};
398				});
399		}
400	
401		/** The actual review cards (with live SRS state) for a pending catch-up. */
402		getPendingCatchUpCards(lessonNumber: number): PropertyCard[] {
403			const pending = this.stateRepo
404				.getPendingCatchUps()
405				.find((p) => p.lessonNumber === lessonNumber);
406			if (!pending) return [];
407	
408			const idSet = new Set(pending.cardIds);
409			return (this.cardRepo.findAll("script") as ScriptPropertyCard[])
410				.filter((card) => idSet.has(card.id))
411				.map((card) => card.toDTO() as PropertyCard);
412		}
413	
414		/** Marks a pending catch-up as seen once the learner completes its intro. */
415		dismissPendingCatchUp(lessonNumber: number): void {
416			this.stateRepo.clearPendingCatchUp(lessonNumber);
417		}
418	}
