			if (sym.lesson != null && completedLessons.has(sym.lesson)) {
				chars.add(sym.character);
			}
		}
		for (const sym of vowels) {
			if (sym.lesson != null && completedLessons.has(sym.lesson)) {
				for (const ch of sym.character) {
					if ("\u0e00" <= ch && ch <= "\u0e7f") {
						chars.add(ch);
					}
				}
			}
		}
		for (const sym of toneMarks) {
			if (sym.lesson != null && completedLessons.has(sym.lesson)) {
				chars.add(sym.character);
			}
		}

		return chars;
	}

